mapper.select:
SELECT p.project_sq AS projectSq, p.project_ttl AS projectTtl, c.company_nm AS companyNm, p.project_recruit_start_dt AS recruitStartDt, p.project_recruit_end_dt AS recruitEndDt, p.project_candidate_cnt AS candidateCnt, p.project_view_cnt AS viewCnt, (SELECT COUNT(*) FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_RESUME_M r ON r.resume_sq = a.resume_sq JOIN TBL_USER_M u ON u.user_sq = r.user_sq WHERE a.project_sq = p.project_sq AND ) AS botApplicationCnt FROM TBL_PROJECT_M p LEFT JOIN TBL_COMPANY_S c ON c.company_sq = p.company_sq WHERE p.project_is_deleted_yn = 'N'
AND p.project_sq IN #{sq}
ORDER BY p.project_view_cnt DESC, p.project_sq

mapper.update:
UPDATE TBL_PROJECT_M
   SET project_candidate_cnt = GREATEST(0, COALESCE(project_candidate_cnt, 0) + #{delta})
 WHERE project_sq = #{projectSq}

mapper.select:
SELECT a.project_sq AS projectSq, p.project_ttl AS projectTtl, COUNT(*) AS count FROM TBL_PROJECT_APPLICATION_H a JOIN TBL_RESUME_M r ON r.resume_sq = a.resume_sq JOIN TBL_USER_M u ON u.user_sq = r.user_sq JOIN TBL_PROJECT_M p ON p.project_sq = a.project_sq WHERE
AND a.project_sq IN #{sq}
GROUP BY a.project_sq, p.project_ttl ORDER BY COUNT(*) DESC
